import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import path from "node:path";

/**
 * Speech-to-text provider.
 *  - OPENAI_API_KEY set  -> OpenAI transcription (multilingual incl. Yoruba / Hausa)
 *  - otherwise           -> simulator: looks the audio up by SHA-256 in
 *                           public/demo/audio/manifest.json (clips generated by scripts/seed.ts)
 */
export interface Transcription {
  text: string;
  engine: "openai" | "simulator";
}

export async function transcribe(audio: Buffer, filename: string, mime: string): Promise<Transcription> {
  if (process.env.OPENAI_API_KEY) {
    const form = new FormData();
    form.set("file", new Blob([new Uint8Array(audio)], { type: mime }), filename);
    form.set("model", "whisper-1");
    const res = await fetch("https://api.openai.com/v1/audio/transcriptions", {
      method: "POST",
      headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
      body: form,
    });
    if (!res.ok) throw new Error(`STT failed: ${res.status}`);
    const json = (await res.json()) as { text: string };
    return { text: json.text, engine: "openai" };
  }
  const hash = createHash("sha256").update(audio).digest("hex");
  try {
    const manifest = JSON.parse(
      await readFile(path.join(process.cwd(), "public/demo/audio/manifest.json"), "utf8"),
    ) as Record<string, { transcript: string }>;
    const hit = manifest[hash];
    if (hit) return { text: hit.transcript, engine: "simulator" };
  } catch {
    /* no manifest */
  }
  throw new Error(
    "No speech-to-text provider configured and this audio is not a known demo clip. Set OPENAI_API_KEY or paste the transcript.",
  );
}
